const embedding = $json.embeddings?.[0];
if (!Array.isArray(embedding) || embedding.length !== 768 || !embedding.every(Number.isFinite)) {
  throw new Error("Expected 768 finite embedding values from Ollama");
}

return { json: { statement: "MERGE (r:Recipe {id: $recipe.id})\nSET r += {title: $recipe.title, text: $recipe.text, minutes: $recipe.minutes,\n          source: $recipe.source, embedding: $embedding, embeddingModel: $model}\nRETURN r.id AS id", parameters: { recipe: $("Recipe data").item.json, embedding, model: "nomic-embed-text:v1.5" } } };

if ($json.errors?.length) throw new Error(JSON.stringify($json.errors));
const { fields, values } = $json.data ?? {};
if (!Array.isArray(fields) || !Array.isArray(values)) throw new Error("Unexpected Neo4j response");
return { json: { results: values.map(row =>
  Object.fromEntries(fields.map((field, index) => [field, row[index]]))
) } };

